#pragma once

// Contract between code generated by cpusim-devc and the runtime that runs it
// (DESIGN.md 6.4). Changing anything here means bumping CPUSIM_KERNEL_ABI.
//
// A module is a native shared object exporting, per kernel,
//     uint32_t __cpusim_entry_<mangled name>(const cpusim_warp_ctx*);
// which runs ONE warp of one block from start to the next barrier or the end,
// and returns a cpusim_exit_reason; and an instrumented twin
//     uint32_t __cpusim_prof_<mangled name>(const cpusim_warp_ctx*);
// that also adds to ctx->counters what the warp executed (see cpusim_counter).
// Per kernel there is also
//     const cpusim_kernel_meta __cpusim_meta_<mangled name>;
// and per module
//     const uint32_t __cpusim_abi_version;
//
// Barriers: when a warp reaches __syncthreads it saves its state in its frame
// (ctx->frame, frame_bytes per warp, zeroed before the block starts) and
// returns CPUSIM_BARRIER. The runtime runs every warp of the block up to the
// barrier, then calls each entry again; the entry sees the saved state and
// resumes after the barrier.

#include <stddef.h>
#include <stdint.h>

#define CPUSIM_KERNEL_ABI 13
#define CPUSIM_WARP_SIZE 32   // CUDA's warp, the default (cpusim_kernel_meta.warp_size has the module's)
#define CPUSIM_MAX_LANES 512  // widest group of threads one entry call runs

// Besides the 32-lane entry, a module has "block-wide" variants
//     uint32_t __cpusim_entry<L>_<mangled name>(const cpusim_warp_ctx*);
// for L = 64, 128, 256, 512 lanes (listed in cpusim_kernel_meta.flags). When a
// whole block fits in one call, its threads run in lockstep and __syncthreads
// costs nothing: no frame, no resume. The runtime picks the smallest variant
// that covers the block for kernels with barriers.
//
// Kernels with barriers also get "suspending" variants of 64 and 128 lanes,
//     uint32_t __cpusim_entry<L>s_<mangled name>(const cpusim_warp_ctx*);
// which behave like the 32-lane entry (save state, return at a barrier) for
// groups of 2 or 4 warps: fewer switches per barrier. frame_bytes covers them.
//
// And "cooperative" variants of 64, 128, 256 and 512 lanes,
//     uint32_t __cpusim_entry<L>c_<mangled name>(const cpusim_warp_ctx*);
// for blocks of L+1 to 2L threads: the two SMT siblings of a core run the two
// halves of one block at the same time (warp_index 0 and L/32), sharing its
// shared memory. Each __syncthreads is inline code (no call: a call would
// spill every vector register): bump this half's epoch, wait until the other
// half's epoch is at least as high. No frames, no suspending.

enum cpusim_exit_reason {
    CPUSIM_EXIT = 0,     // the group finished
    CPUSIM_BARRIER = 1,  // reached __syncthreads; call again to resume (32-lane entry only)
    CPUSIM_YIELD = 2,    // spinning on memory another warp of the block writes: run the
                         // others, then call again (same barrier count as before)
};

// One call's context: this 128-byte header, followed by the per-lane data
// sized for the entry's width (cpusim_ctx_size):
//     uint32_t tid_x[lanes], tid_y[lanes], tid_z[lanes];   // thread index per lane
//     uint32_t lane_mask[lanes / 32];                        // bit set: real thread
// Compact on purpose: a block's contexts must stay in L1 while its warps take
// turns at barriers.
typedef struct __attribute__((aligned(64))) cpusim_warp_ctx {
    uint32_t lanes;         // lanes in this call (the entry's width)
    uint32_t warp_index;    // first warp of this group inside the block
    uint32_t block_idx[3];
    uint32_t block_dim[3];
    uint32_t grid_dim[3];
    // Set by the runtime when every other warp of the block already reached
    // this warp's next barrier: the warp goes through it instead of
    // suspending (one context switch less). Valid for one barrier per call.
    uint32_t barrier_pass;
    const uint8_t* params;  // kernel arguments, laid out as in the module manifest
    uint8_t* shared;        // the block's shared memory
    uint64_t* counters;     // CPUSIM_COUNTERS slots, only used by the __cpusim_prof_ entry
    uint8_t* frame;         // this group's saved state across barriers (64-byte aligned)
    // Cooperative variants: barrier epochs of this half and of the other one,
    // each on its own cache line. The runtime sets both halves' epochs to the
    // same value before a block, and a half that returns sets its epoch to
    // that value | 0xffffffff, so the other one never waits for it again.
    uint64_t* coop_epoch;
    const uint64_t* coop_other;
    // The span [huge_lo, huge_hi] of every object of 2 GiB or more the kernel
    // can reach (VRAM and shared pool allocations; device malloc refuses
    // them); huge_lo > huge_hi when there is none. An access p[i] stays inside
    // p's object, so when p is outside the span its byte offset from p fits in
    // 32 signed bits and gathers and scatters use 32-bit indices. huge_hi is
    // inclusive: a pointer one past a huge object may still index back into
    // it. (Shared memory and per-thread arrays are always small.)
    uint64_t huge_lo, huge_hi;
} cpusim_warp_ctx;

#define CPUSIM_CTX_HEADER 128
#define CPUSIM_CTX_TID(lanes, dim) (CPUSIM_CTX_HEADER + 4 * (lanes) * (dim))
#define CPUSIM_CTX_LANE_MASK(lanes) (CPUSIM_CTX_HEADER + 12 * (lanes))

static inline uint32_t cpusim_ctx_size(uint32_t lanes) {
    return (CPUSIM_CTX_LANE_MASK(lanes) + lanes / 8 + 63) & ~63u;
}
static inline uint32_t* cpusim_ctx_tid(cpusim_warp_ctx* c, int dim) {
    return (uint32_t*)((char*)c + CPUSIM_CTX_TID(c->lanes, dim));
}
static inline uint32_t* cpusim_ctx_lane_mask(cpusim_warp_ctx* c) {
    return (uint32_t*)((char*)c + CPUSIM_CTX_LANE_MASK(c->lanes));
}

// Profile counters. Operation counts are per thread, like the GPU profilers
// report them: an operation executed by a warp with 20 active lanes counts 20.
// Counted on the per-thread code, before vectorization.
enum cpusim_counter {
    CPUSIM_CNT_FP32_FLOPS = 0,   // fadd/fsub/fmul/fdiv = 1, fma = 2 (single precision)
    CPUSIM_CNT_FP64_FLOPS,       // same, double precision
    CPUSIM_CNT_FP_SPECIAL,       // sqrt, exp, sin, ... (any precision)
    CPUSIM_CNT_INT_OPS,          // integer arithmetic, logic and compares
    CPUSIM_CNT_LOADS,            // memory loads (global, shared, local)
    CPUSIM_CNT_STORES,
    CPUSIM_CNT_LOAD_BYTES,
    CPUSIM_CNT_STORE_BYTES,
    CPUSIM_CNT_BRANCHES,         // conditional branches
    CPUSIM_CNT_BLOCK_RUNS,       // basic blocks executed by a warp (warp level)
    CPUSIM_CNT_ACTIVE_LANES,     // sum of active lanes over those executions
    CPUSIM_COUNTERS = 16
};

#define CPUSIM_META_HAS_BARRIERS 1u
// Variant bits, with W = warp_size (32: the 64..512-lane variants):
#define CPUSIM_META_WIDE_SHIFT 8   // bit (8 + i): block-wide variant with 2W << i lanes exists
#define CPUSIM_META_SUSP_SHIFT 16  // bit (16 + i): suspending variant __cpusim_entry<2W << i>s_ exists (i < 2)
#define CPUSIM_META_COOP_SHIFT 24  // bit (24 + i): cooperative variant __cpusim_entry<2W << i>c_ exists
#define CPUSIM_META_BLOCK_FN 2u    // __cpusim_block_<name> exists (see below)
#define CPUSIM_META_YIELDS 4u      // the 32-lane entry may return CPUSIM_YIELD (no barrier pass-through)
// No lane ever sees another's state (no barrier, shared memory, shuffle,
// ballot, match or tensor core op): any subset of a group's lanes can run as
// a call of its own, on its own worker.
#define CPUSIM_META_LANE_INDEPENDENT 8u

// Kernels with barriers also get
//     uint32_t __cpusim_block_<mangled name>(cpusim_warp_ctx* ctxs, uint32_t nwarps, uint8_t* done);
// which runs a whole block: rounds over its 32-lane warps (ctxs[0..nwarps)),
// each up to the next barrier, with the warp code inlined. The caller zeroes
// every frame's state word and done[].

typedef struct cpusim_kernel_meta {
    uint32_t abi;
    uint32_t frame_bytes;   // per 32-lane warp; 0 without barriers
    uint32_t shared_bytes;  // static __shared__ memory per block
    uint32_t flags;         // CPUSIM_META_*
    uint32_t frame_bytes_wide[2];  // per group, for the suspending variants of 2 and 4 warps
    // Threads per warp the code was written against (16, 32 or 64), and the
    // lanes of __cpusim_entry_ (the warp size, or fewer for a block smaller
    // than a warp: the lanes of threads that do not exist are left out).
    uint32_t warp_size;
    uint32_t warp_lanes;
} cpusim_kernel_meta;

// Distance between consecutive contexts or frames of one block: an odd number
// of cache lines, so the warps' data does not pile up in the same L1 sets.
static inline uint32_t cpusim_stagger(uint32_t bytes) {
    uint32_t lines = (bytes + 63) / 64;
    return (lines | 1u) * 64;
}

// Header offsets the code generator relies on.
#define CPUSIM_CTX_LANES 0
#define CPUSIM_CTX_WARP_INDEX 4
#define CPUSIM_CTX_BLOCK_IDX 8
#define CPUSIM_CTX_BLOCK_DIM 20
#define CPUSIM_CTX_GRID_DIM 32
#define CPUSIM_CTX_BARRIER_PASS 44
#define CPUSIM_CTX_PARAMS 48
#define CPUSIM_CTX_SHARED 56
#define CPUSIM_CTX_COUNTERS 64
#define CPUSIM_CTX_FRAME 72
#define CPUSIM_CTX_COOP_EPOCH 80
#define CPUSIM_CTX_COOP_OTHER 88
#define CPUSIM_CTX_HUGE_LO 96
#define CPUSIM_CTX_HUGE_HI 104

#ifdef __cplusplus
static_assert(sizeof(cpusim_warp_ctx) == CPUSIM_CTX_HEADER);
static_assert(offsetof(cpusim_warp_ctx, warp_index) == CPUSIM_CTX_WARP_INDEX);
static_assert(offsetof(cpusim_warp_ctx, block_idx) == CPUSIM_CTX_BLOCK_IDX);
static_assert(offsetof(cpusim_warp_ctx, block_dim) == CPUSIM_CTX_BLOCK_DIM);
static_assert(offsetof(cpusim_warp_ctx, grid_dim) == CPUSIM_CTX_GRID_DIM);
static_assert(offsetof(cpusim_warp_ctx, barrier_pass) == CPUSIM_CTX_BARRIER_PASS);
static_assert(offsetof(cpusim_warp_ctx, params) == CPUSIM_CTX_PARAMS);
static_assert(offsetof(cpusim_warp_ctx, shared) == CPUSIM_CTX_SHARED);
static_assert(offsetof(cpusim_warp_ctx, counters) == CPUSIM_CTX_COUNTERS);
static_assert(offsetof(cpusim_warp_ctx, frame) == CPUSIM_CTX_FRAME);
static_assert(offsetof(cpusim_warp_ctx, coop_epoch) == CPUSIM_CTX_COOP_EPOCH);
static_assert(offsetof(cpusim_warp_ctx, coop_other) == CPUSIM_CTX_COOP_OTHER);
static_assert(offsetof(cpusim_warp_ctx, huge_lo) == CPUSIM_CTX_HUGE_LO);
static_assert(offsetof(cpusim_warp_ctx, huge_hi) == CPUSIM_CTX_HUGE_HI);
#endif

typedef uint32_t (*cpusim_entry_fn)(const cpusim_warp_ctx*);
typedef uint32_t (*cpusim_block_fn)(cpusim_warp_ctx* ctxs, uint32_t nwarps, uint8_t* done);

// The "fatbin" the compiler embeds in the application (clang puts it in
// .nv_fatbin and passes it to __cudaRegisterFatBinary through a wrapper).
//   header | manifest (text) | shared object | device bitcode (optional)
//          | specialized objects: a table, then each shared object
// Manifest lines:
//   kernel <mangled name> <param bytes> <count> <offset>:<size> ...
// The bitcode is the per-thread device code (the role of PTX): the runtime
// recompiles it at launch, specialized for the block shape (JIT), unless the
// compiler already did for that shape (block shapes constant at the launches
// it saw): those objects come ready in the table.
#define CPUSIM_FATBIN_MAGIC "CPUSIMFB"

typedef struct cpusim_fatbin_header {
    char magic[8];
    uint32_t version;       // CPUSIM_KERNEL_ABI
    uint32_t reserved;
    uint64_t manifest_offset, manifest_size;
    uint64_t object_offset, object_size;
    uint64_t bitcode_offset, bitcode_size;  // size 0: no bitcode
    uint64_t specialized_offset, specialized_count;  // table of cpusim_fatbin_specialized
} cpusim_fatbin_header;

// A shared object of the module specialized for one block shape, as the JIT
// would build it; offset from the start of the fatbin.
typedef struct cpusim_fatbin_specialized {
    uint32_t block[3];
    uint32_t reserved;
    uint64_t offset, size;
} cpusim_fatbin_specialized;
